import json
import os
import urllib.request

# The pricing service was moved to v2.  Keeping this as one configurable value
# also makes endpoint changes possible without touching application code.
BASE = os.environ.get(
    "PRICING_URL", "http://pricing-v2-d6c12d17:8081/api/v2/price"
)


def get_price(sku: str) -> float:
    request = urllib.request.Request(f"{BASE}/{sku}")
    if key := os.environ.get("PRICING_KEY"):
        request.add_header("X-Pricing-Key", key)
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
